window.NGN_EXTRA['48'] = [
  { f: 'matrix', t: 'Small or large bowel obstruction?', q: 'For each finding, indicate whether it fits a small-bowel or a large-bowel obstruction.',
    cols: ['Small-bowel obstruction', 'Large-bowel obstruction'],
    rows: [{ t: 'Early, profuse vomiting', a: 0, r: 'Small bowel. The higher the block, the sooner and more profusely the client vomits.' },
      { t: 'Ribbon-like stools or obstipation, little or no vomiting', a: 1, r: 'Large bowel. The block is far down, so contents back up slowly.' },
      { t: 'Upper or epigastric distention', a: 0, r: 'Small bowel. Distention sits where the loops are filling.' },
      { t: 'Intermittent lower abdominal cramping with lower distention', a: 1, r: 'Large bowel.' },
      { t: 'Severe fluid and electrolyte loss; possible metabolic alkalosis', a: 0, r: 'Small bowel. A high block loses gastric acid and large volumes of secretions.' }],
    ask: 'How does the height of the block change what you see?', cues: ['High block → early vomiting, alkalosis', 'Low block → distention, little vomiting'],
    phys: 'Contents pile up above the block → the higher it is, the sooner they are vomited (losing gastric acid → alkalosis) → a low block fills the colon slowly → lower distention and obstipation, with alkaline fluid loss tending toward acidosis.',
    rule: 'Small: epigastric distention, early profuse vomiting, big fluid and electrolyte losses. Large: lower distention, cramping, little vomiting, ribbon stools or none.' },

  { f: 'matrix', t: 'Mechanical or paralytic?', q: 'For each finding, indicate whether it fits a mechanical obstruction or a paralytic ileus.',
    cols: ['Mechanical obstruction', 'Paralytic ileus'],
    rows: [{ t: 'High-pitched bowel sounds early, then silence', a: 0, r: 'Mechanical. The bowel works hard against the block (borborygmi), then tires.' },
      { t: 'Bowel sounds decreased, then absent', a: 1, r: 'Paralytic. Peristalsis has slowed or stopped — there is nothing to push against.' },
      { t: 'Colicky, cramping pain that comes and goes', a: 0, r: 'Mechanical. Each wave of peristalsis hits the block.' },
      { t: 'Constant, diffuse discomfort', a: 1, r: 'Paralytic. No waves, so no colic.' },
      { t: 'Follows bowel handling in abdominal surgery or low potassium', a: 1, r: 'Paralytic. Surgery and hypokalemia disturb the nerves and muscle of the bowel wall.' },
      { t: 'Caused by adhesions, a tumor or volvulus', a: 0, r: 'Mechanical. Something physically blocks the lumen.' }],
    ask: 'Is something blocking the tube, or has the tube stopped moving?', cues: ['Block → colic and loud sounds', 'No motility → constant ache and silence'],
    phys: 'Mechanical: peristalsis pushes against a block → cramping waves and high-pitched rushes → later the wall fatigues and goes quiet. Paralytic: nerves and muscle stop the waves (surgery, low K⁺, peritonitis) → contents sit → distention without colic.',
    rule: 'Mechanical = colicky pain, borborygmi then silence. Paralytic = constant discomfort, sounds decreased then absent; responds well to NG decompression and fixing K⁺.' },

  { f: 'exhibit', t: 'Day 2 of a bowel obstruction', q: 'Review the flow sheet for a client with a small-bowel obstruction from adhesions, managed with NG suction. What should the nurse do?',
    ex: [{ h: 'Flow sheet', table: [['', 'Day 1, 08:00', 'Day 2, 08:00', 'Day 2, 14:00'], ['Temperature', '99.0°F', '99.8°F', '101.4°F'], ['Heart rate', '92', '104', '122'], ['Pain', 'Cramping, comes and goes, 6/10', 'Cramping 6/10', 'Constant, right side, 9/10'], ['Abdomen', 'Distended, soft', 'Distended', 'Tender, guarding']] }],
    o: ['Report the findings to the provider immediately', 'Give the PRN morphine and reassess in an hour', 'Irrigate the NG tube with 30 mL saline', 'Document — these changes are expected on day 2'], a: [0],
    r: ['Correct. Fever over 100°F with a rising pulse and pain that turned from colicky to constant and localized = strangulation, ischemia or peritonitis — a surgical emergency.',
      'Incorrect. Pain relief matters, but the change in pain is the diagnosis and must reach the provider first; morphine also slows motility.',
      'Incorrect. A plugged tube doesn’t explain fever, tachycardia and constant localized pain.',
      'Incorrect. Uncomplicated obstruction rarely raises temperature above 100°F.'],
    ask: 'What does it mean when colicky pain becomes constant?', cues: ['Temp 101.4°F, HR 92 → 122', 'Colicky → constant and localized', 'Guarding'],
    phys: 'A loop of blocked bowel twists or swells until its blood supply fails → the wall becomes ischemic → it stops contracting (colic ends) and becomes constantly painful → bacteria and endotoxin leak → fever, tachycardia, peritonitis, septic shock.',
    rule: 'Obstruction: temperature > 100°F with a rising pulse, or pain that becomes constant or localized = strangulation until proven otherwise → report now.' },

  { f: 'sata', t: 'Caring for the NG tube', q: 'A client with a bowel obstruction has a Salem sump NG tube to low continuous suction. Which actions are correct? Select all that apply.',
    o: ['Check placement, patency and output at least every 4 hours', 'Turn the suction off to listen for bowel sounds', 'Irrigate with 30 mL normal saline as ordered', 'Give frequent mouth and nares care', 'Listen for bowel sounds with the suction running', 'Clamp the blue vent (“pigtail”) to stop it leaking', 'Report increasing nausea and distention with less drainage'], a: [0, 1, 2, 3, 6],
    r: ['Correct. The tube only helps if it is in the stomach and draining.',
      'Correct. Suction gurgles — the nurse would “hear” peristalsis that isn’t there.',
      'Correct. Saline irrigation clears a plugged tube when ordered.',
      'Correct. NPO and a tube in the nose dry and irritate the mouth and nares.',
      'Incorrect. Suction noise masks or mimics bowel sounds.',
      'Incorrect. The vent lets air in so the stomach lining isn’t pulled into the tube; it should stay open.',
      'Correct. Less output with more nausea and distention means the tube is out of position or plugged.'],
    ask: 'How does the nurse know the tube is doing its job?', cues: ['Salem sump → vent must stay open', 'Bowel sounds → suction off'],
    phys: 'The NG tube removes the fluid and air piling up above the block → the bowel decompresses → less pressure on the wall, less vomiting, less fluid leaking out of the circulation.',
    rule: 'NG for obstruction: low continuous suction, vent open, check every 4 h, listen with suction off, irrigate as ordered, report less output with more distention.' },

  { f: 'bow', t: 'After a car crash', q: 'A driver in a car crash (seat belt on) has left shoulder pain with no shoulder injury, a distended abdomen and purple bruising around the umbilicus. BP 92/58 (was 128/80), HR 126, restless.',
    cond: { o: ['Intra-abdominal hemorrhage (possible ruptured spleen)', 'Shoulder dislocation', 'Paralytic ileus', 'Hollow-viscus perforation with septic shock'], a: 0,
      r: ['Correct. Kehr sign (left shoulder pain from blood irritating the diaphragm) and Cullen sign (periumbilical bruising) with a falling BP and rising HR = bleeding into the abdomen.', 'Incorrect. There is no shoulder injury — the pain is referred.', 'Incorrect. Ileus doesn’t cause shock or bruising.', 'Incorrect. Perforation causes peritonitis and sepsis over hours; this is fast blood loss.'] },
    act: { o: ['Call for the team and prepare for emergency surgery', 'Start two large-bore IVs for fluid and blood', 'Apply ice to the left shoulder', 'Give oral fluids', 'Palpate deeply to find the source'], a: [0, 1],
      r: ['Correct. Unstable or actively bleeding → straight to laparotomy.', 'Correct. Volume and blood replacement while surgery is arranged.', 'Incorrect. The shoulder isn’t injured.', 'Incorrect. NPO for surgery.', 'Incorrect. Significant palpation is the trained provider’s, and it won’t stop the bleeding.'] },
    mon: { o: ['Vital signs and level of consciousness', 'Hemoglobin and hematocrit', 'Bowel sounds every hour', 'Pupils', 'Capillary glucose'], a: [0, 1],
      r: ['Correct. Track shock.', 'Correct. Track blood loss.', 'Incorrect. Not what guides this emergency.', 'Incorrect. No head injury described.', 'Incorrect. Not related.'] },
    ask: 'What do referred shoulder pain and periumbilical bruising mean after blunt trauma?', cues: ['Kehr sign → blood under the diaphragm', 'Cullen sign → blood in the abdominal wall', 'BP falling, HR rising → hypovolemic shock'],
    phys: 'Blunt deceleration tears the spleen or liver → blood fills the abdomen → it irritates the diaphragm and the phrenic nerve (C3–C5, the same level as shoulder nerves) → left shoulder pain; it tracks into the abdominal wall → Cullen sign; volume falls → shock.',
    rule: 'Abdominal trauma: Kehr, Cullen, Turner signs and distention mean bleeding; unstable → surgery; FAST scan finds free fluid fast.' },

  { f: 'cloze', t: 'Where the tumor sits', q: 'Complete the statement.',
    parts: ['Stool in the right (ascending) colon is ', { o: ['liquid', 'formed'], a: 0, r: 'The colon hasn’t absorbed much water yet, so stool flows around a growing mass.' },
      ', so right-sided tumors often show first as ', { o: ['anemia from slow, intermittent bleeding', 'ribbon-like stools'], a: 0, r: 'Bowel habits don’t change; the tumor ulcerates and bleeds slowly (mahogany stool) → anemia and fatigue.' },
      ', while rectosigmoid tumors cause ', { o: ['narrow stools, straining and bright red blood', 'a right lower quadrant mass'], a: 0, r: 'Formed stool is narrowed by the mass and streaked with blood that hasn’t had time to darken.' },
      '. The most common site of colorectal cancer spread is the ', { o: ['liver', 'brain', 'bone'], a: 0, r: 'Colon blood drains through the portal vein to the liver first.' }, '.'],
    ask: 'How does tumor location change the first sign?', cues: ['Right colon = liquid stool', 'Left colon = formed stool'],
    phys: 'The colon absorbs water as stool moves along → liquid on the right, formed on the left → a right-sided mass bleeds slowly without blocking (anemia) → a left-sided mass narrows and blocks formed stool and adds bright red blood → portal venous drainage carries cells to the liver.',
    rule: 'Right-sided CRC: anemia, mahogany blood, RLQ mass. Left/rectosigmoid: obstruction, narrow stools, bright red blood. Colonoscopy is the definitive test; CEA monitors.' },

  { f: 'sata', t: 'Colostomy teaching', q: 'Which instructions should the nurse include when teaching a client to care for a new colostomy? Select all that apply.',
    o: ['Empty the pouch when it is one-third to one-half full', 'Measure the stoma weekly and cut the opening ⅛–1/16 inch larger', 'Clean the skin with mild soap and water, not moisturizing soap', 'Report a stoma that turns dark red, purple or black', 'Put an aspirin in the pouch to control odor', 'Cut the wafer opening exactly the size of the stoma', 'A healthy stoma is pale pink and dry'], a: [0, 1, 2, 3],
    r: ['Correct. A heavier pouch pulls on the seal and leaks.',
      'Correct. The stoma shrinks for 6–8 weeks; a slightly larger opening protects it without exposing much skin.',
      'Correct. Moisturizing soap leaves a film that stops the wafer from sticking.',
      'Correct. Dark, purple, black or dry means the stoma is losing its blood supply.',
      'Incorrect. Aspirin can ulcerate the stoma. Odor usually means a leak — use filters or deodorizers.',
      'Incorrect. A tight opening cuts the stoma, which has no pain nerves to warn the client.',
      'Incorrect. A healthy stoma is reddish pink to dark red-pink and moist.'],
    ask: 'Which steps keep the stoma healthy and the seal intact?', cues: ['Stoma has no pain nerves', 'Color = blood supply'],
    phys: 'A stoma is bowel mucosa turned out onto the skin → it has blood supply but no pain nerves → its color shows perfusion, and only a correct fit protects it from cuts and the skin from stool.',
    rule: 'Ostomy: empty at ⅓–½ full; measure weekly, cut ⅛–1/16 inch larger; mild soap, alcohol-free sealant; report dark, dry, bleeding or separating stoma; never aspirin in the pouch.' },

  { f: 'order', t: 'Changing the pouch', q: 'Place the steps for changing a colostomy pouch in order.',
    o: ['Gently remove the old pouch, pushing the skin away from the wafer', 'Clean the skin with mild soap and water and pat it dry', 'Measure the stoma and cut the wafer opening ⅛–1/16 inch larger', 'Apply alcohol-free skin sealant and let it dry', 'Apply the new pouch and press the wafer around the stoma'], a: [0, 1, 2, 3, 4],
    r: ['First: pushing the skin away (not pulling the wafer) avoids skin stripping.',
      'Second: clean, dry skin lets the new wafer stick.',
      'Third: the stoma shrinks for weeks — measure each time early on.',
      'Fourth: sealant protects the skin; it must dry or the wafer won’t adhere.',
      'Last: press around the stoma for a good seal.'],
    ask: 'What order protects the skin and gives a seal that lasts?', cues: ['Remove → clean → measure → protect → apply'],
    phys: 'Adhesive pulled off skin strips the top layer → stool on damaged skin causes irritant dermatitis → a dry, sealed surface and a correctly sized opening keep stool off the skin.',
    rule: 'Pouch change: remove gently → mild soap and water, dry → measure and cut ⅛–1/16 inch larger → alcohol-free sealant, let dry → apply.' },

  { f: 'sata', t: 'After inguinal hernia repair', q: 'Which instructions are appropriate after a minimally invasive inguinal hernia repair? Select all that apply.',
    o: ['Take deep breaths, but avoid coughing', 'Use ice packs and a scrotal support', 'Men may stand to void', 'Report urine output below 30 mL an hour', 'Lift no more than 10 lb until cleared', 'Cough forcefully every hour to clear the lungs', 'Apply heat to the scrotum for swelling'], a: [0, 1, 2, 3, 4],
    r: ['Correct. Deep breathing protects the lungs; coughing spikes pressure on the fresh repair.',
      'Correct. Ice and support reduce scrotal swelling, especially after indirect inguinal repair.',
      'Correct. Standing helps men void after groin surgery and anesthesia.',
      'Correct. Urinary retention is common; report UO < 30 mL/hr (straight catheter if unable to void).',
      'Correct. Heavy lifting raises intraabdominal pressure on the repair.',
      'Incorrect. Coughing strains the repair; use deep breathing and incentive spirometry.',
      'Incorrect. Heat increases swelling; use ice.'],
    ask: 'Which choices protect a fresh repair from pressure — and catch retention?', cues: ['Hernia = pressure + weak wall'],
    phys: 'A hernia forms where raised abdominal pressure pushes through a weak spot → after repair, coughing, lifting and straining push on the same spot → swelling and anesthesia can block voiding.',
    rule: 'After hernia repair: deep breathe, don’t cough, ice and scrotal support, stand to void, report UO < 30 mL/hr, ≤ 10 lb lifting, fiber and fluids.' },

  { f: 'exhibit', t: 'Alosetron', q: 'Review the phone note. What should the nurse tell the client?',
    ex: [{ h: 'Phone note', lines: ['32-year-old woman with IBS-D started alosetron 3 weeks ago.', '“Since yesterday I’ve had cramping that keeps getting worse and some blood with diarrhea. Should I take another dose?”'] }],
    o: ['Stop the alosetron and be seen right away', 'Take the next dose with food', 'Double the fiber and keep taking the drug', 'Bloody diarrhea is expected for the first month'], a: [0],
    r: ['Correct. Worsening pain and bloody diarrhea on alosetron can mean ischemic colitis — stop the drug and report at once.', 'Incorrect. Food doesn’t prevent ischemic colitis.', 'Incorrect. Fiber doesn’t treat ischemia.', 'Incorrect. Bleeding is never expected.'],
    ask: 'What serious effect does alosetron carry?', cues: ['Alosetron + worsening pain + rectal bleeding → ischemic colitis'],
    phys: 'Alosetron blocks 5-HT₃ receptors and slows the gut → in some women blood flow to the colon wall falls → ischemic colitis: pain and bloody diarrhea; severe constipation is also a warning.',
    rule: 'Alosetron (women, IBS-D, last resort): stop and report severe constipation, worsening pain, bloody diarrhea or rectal bleeding.' },

  { f: 'matrix', t: 'Matching IBS drugs to the main symptom', q: 'For each drug, indicate which kind of irritable bowel syndrome (IBS) it is used for.',
    cols: ['Constipation-predominant (IBS-C)', 'Diarrhea-predominant (IBS-D)', 'Pain-predominant'],
    rows: [{ t: 'Linaclotide', a: 0, r: 'IBS-C. It stimulates guanylate cyclase receptors so the bowel secretes more fluid and moves faster, and it eases pain and cramping. Once a day, about 30 minutes before breakfast.' },
      { t: 'Lubiprostone', a: 0, r: 'IBS-C. It increases fluid in the intestine; approved for women and taken with food and water.' },
      { t: 'Loperamide', a: 1, r: 'IBS-D. An antidiarrheal that slows transit.' },
      { t: 'Alosetron', a: 1, r: 'IBS-D. A 5-HT₃ antagonist for women, used with caution as a last resort because it can cause ischemic colitis and severe constipation.' },
      { t: 'Rifaximin', a: 1, r: 'IBS-D. An antibiotic that acts in the gut with little absorption; used for bloating and a swollen abdomen without constipation.' },
      { t: 'Amitriptyline', a: 2, r: 'Pain-predominant. A tricyclic antidepressant; if pain follows meals, it is taken 30–45 minutes before eating.' }],
    ask: 'Does the drug add water and speed the bowel, slow it down, or ease the pain?', cues: ['IBS-C → more fluid, faster transit', 'IBS-D → slower transit, fewer bacteria', 'Pain → tricyclic'],
    phys: 'IBS-C: stool moves slowly and dries → linaclotide and lubiprostone pull fluid into the lumen → softer stool, faster transit. IBS-D: transit is fast or bacteria overgrow → loperamide and alosetron slow the gut, rifaximin reduces the bacteria. Pain from visceral hypersensitivity → a tricyclic helps (whether through its antidepressant or anticholinergic effect is unclear).',
    rule: 'IBS-C: psyllium with water at meals, lubiprostone (women, with food and water), linaclotide (30 min before breakfast). IBS-D: loperamide, psyllium, alosetron (women, last resort), rifaximin. Pain: amitriptyline before meals.' },

  { f: 'bow', t: 'Vomiting and no flatus years after surgery', q: 'A 67-year-old client who had a hysterectomy 3 years ago has had 14 hours of midabdominal cramping that comes in waves, repeated vomiting of greenish bile and no flatus since last night. The abdomen is distended with high-pitched rushes on auscultation; mucous membranes are dry. T 99.0°F, HR 96, BP 108/68. Na⁺ 133 mEq/L, K⁺ 3.2 mEq/L, BUN 28 mg/dL.',
    cond: { o: ['Small-bowel obstruction from adhesions', 'Paralytic ileus', 'Irritable bowel syndrome flare', 'Strangulated obstruction with peritonitis'], a: 0,
      r: ['Correct. Past abdominal surgery (adhesions), colicky midabdominal waves, early bilious vomiting, distention, no flatus and high-pitched sounds above the block = mechanical small-bowel obstruction.', 'Incorrect. Ileus causes constant, diffuse discomfort with bowel sounds decreased or absent — not colicky waves with high-pitched rushes.', 'Incorrect. IBS doesn’t stop flatus or cause bilious vomiting and distention like this; a client with IBS usually looks well.', 'Incorrect. Not yet: the temperature is below 100°F, the pulse isn’t climbing, and the pain still comes in waves without rigidity. Those are the changes to watch for.'] },
    act: { o: ['Keep the client NPO and insert an NG tube to low continuous suction', 'Start IV isotonic fluid (normal saline or lactated Ringer’s) with potassium as prescribed', 'Give a tap-water enema to move the blockage', 'Offer clear liquids to replace what was vomited', 'Lay the client flat and supine'], a: [0, 1],
      r: ['Correct. Decompression drains the fluid and air piling up above the block and relieves vomiting and distention.', 'Correct. Vomiting, NPO and suction drain sodium and potassium; isotonic fluid with K⁺ restores volume (watch for overload in older or cardiac clients).', 'Incorrect. Enemas clear a low fecal impaction, not an adhesion kinking the small bowel.', 'Incorrect. Food and fluids by mouth worsen pain and vomiting — keep NPO.', 'Incorrect. Semi-Fowler eases the pressure of distention on the chest and helps breathing.'] },
    mon: { o: ['Serum potassium and sodium', 'Daily weight with intake and output', 'Capillary glucose every 2 hours', 'Pupil response', 'Peak expiratory flow'], a: [0, 1],
      r: ['Correct. Vomiting and suction keep lowering K⁺ and Na⁺, and low potassium itself slows the bowel.', 'Correct. Daily weight is the most reliable fluid measure; I&O includes NG drainage.', 'Incorrect. Not related to the obstruction.', 'Incorrect. No neurologic problem.', 'Incorrect. No airway disease described.'] },
    ask: 'Is something blocking the bowel, and what does the client need first?', cues: ['Past surgery → adhesions', 'Colicky waves + high-pitched rushes → mechanical', 'Bilious vomiting, no flatus, K⁺ 3.2, BUN 28'],
    phys: 'An adhesion kinks the small bowel → contents and gas pile up above it → peristalsis surges (colic, high-pitched rushes) and secretions increase → vomiting and fluid trapped in the bowel drain sodium, potassium and volume (BUN rises) → NG decompression breaks the cycle and isotonic fluid with K⁺ refills the circulation.',
    rule: 'Suspected bowel obstruction: NPO, NG to low continuous suction, IV isotonic fluid with K⁺, daily weight and I&O, electrolytes; report temperature > 100°F, a rising pulse or pain that turns constant. Partial without strangulation → often nonsurgical; complete mechanical → surgery; strangulated → always surgery.' },

  { f: 'sata', t: 'Handlebar injury in the ED', q: 'A 26-year-old cyclist struck the handlebars with his upper abdomen. In the ED he is alert, reports left upper abdominal pain of 8/10 and has a bruise across the upper abdomen. HR 122, BP 96/62, RR 24, SpO₂ 91% on room air. Which actions should the nurse take? Select all that apply.',
    o: ['Complete the primary survey before a detailed abdominal assessment', 'Apply supplemental oxygen', 'Assist with a bedside FAST scan', 'Inspect the abdomen with the client lying flat, and repeat it often', 'Palpate deeply over the painful area to find the injury', 'Give sips of water for thirst', 'Ask how the injury happened once life threats are managed'], a: [0, 1, 2, 3, 6],
    r: ['Correct. Airway, breathing, circulation and any resuscitation come before the focused abdominal exam.',
      'Correct. SpO₂ 91% with a fast respiratory rate — impaired oxygenation is treated with oxygen, or ventilation if needed.',
      'Correct. A FAST scan quickly shows free fluid (blood or GI contents) in the abdomen.',
      'Correct. Repeated inspection catches new bruising (Cullen, Turner), distention and worsening findings.',
      'Incorrect. Significant palpation and percussion are left to the surgeon or emergency care provider.',
      'Incorrect. He may need emergency surgery — keep him NPO.',
      'Correct. The mechanism of injury (the instrument and the force) hints at which organs may be damaged.'],
    ask: 'What comes first after blunt abdominal trauma, and how is bleeding inside the abdomen found quickly?', cues: ['HR 122, BP 96/62 → possible hemorrhage', 'SpO₂ 91%, RR 24 → oxygen', 'Blunt trauma → FAST for free fluid'],
    phys: 'Blunt force tears a solid organ such as the spleen or liver → blood collects in the abdomen → circulating volume falls (tachycardia, low BP) and less oxygen reaches the tissues → the primary survey supports airway, breathing and circulation → a FAST scan finds the free fluid → unstable bleeding goes to laparotomy.',
    rule: 'Blunt abdominal trauma: primary survey first; oxygen as needed; FAST for free fluid, CT after resuscitation; inspect lying flat and repeat; frequent VS and Hgb/Hct; NPO; significant palpation by the trained provider; unstable → laparotomy.' }
];

window.RECALL_EXTRA['48'] = {
  nclex: [
    { t: 'First bowel movement after hemorrhoidectomy', q: 'What should the nurse plan for a client’s first bowel movement after a hemorrhoidectomy?',
      o: ['Stay with or near the client because of possible fainting', 'Give a strong stimulant laxative the evening of surgery', 'Have the client sit on a rubber donut afterward', 'Withhold pain medication so the client can bear down'], a: [0],
      r: ['Correct. The first bowel movement can be very painful; a vasovagal response can cause light-headedness, sweating and syncope.', 'Incorrect. Stool softeners are used; habit-forming stimulant laxatives are avoided.', 'Incorrect. Sitz baths and moist heat are used for comfort.', 'Incorrect. Give analgesics and softeners; straining is avoided.'],
      ask: 'What makes the first BM risky after anal surgery?', cues: ['Severe pain + straining → vagal response'],
      phys: 'Pain and straining stimulate the vagus nerve → heart rate and BP drop → less blood to the brain → light-headedness and syncope on the toilet.',
      rule: 'After hemorrhoidectomy: softeners, sitz baths 3–4×/day, analgesics, mild laxative if no BM by day 3 — and someone nearby for the first BM.' },
    { t: 'A hernia that won’t go back', q: 'A client has an inguinal hernia that could be pushed back yesterday but cannot be reduced today. What should the nurse do?',
      o: ['Arrange immediate surgical evaluation and don’t push on it', 'Apply firm pressure to push it back', 'Apply a truss over the bulge', 'Teach the client to lie flat until it goes back'], a: [0],
      r: ['Correct. An irreducible (incarcerated) hernia needs immediate surgical evaluation — it can strangulate.', 'Incorrect. Never force a hernia back; strangulated bowel could rupture.', 'Incorrect. A truss goes on only after a hernia is reduced.', 'Incorrect. Waiting delays care for possible strangulation.'],
      ask: 'What makes an irreducible hernia dangerous?', cues: ['Can’t be reduced → incarcerated'],
      phys: 'Bowel trapped in the hernial ring swells → the ring squeezes its blood supply → ischemia (strangulation) → necrosis, obstruction, perforation, sepsis.',
      rule: 'Reducible: may be managed with a truss. Incarcerated: immediate surgical evaluation. Strangulated (pain, fever, tachycardia, distention, vomiting): emergency.' },
    { t: 'Kehr sign', q: 'A trauma client with no shoulder injury reports left shoulder pain. The nurse suspects which problem?',
      o: ['Ruptured spleen with blood irritating the diaphragm', 'Rotator cuff tear', 'Myocardial infarction', 'Pneumonia'], a: [0],
      r: ['Correct. Kehr sign: blood under the diaphragm irritates the phrenic nerve, and pain is referred to the left shoulder.', 'Incorrect. There is no shoulder injury.', 'Incorrect. Possible in other settings, but in abdominal trauma think spleen.', 'Incorrect. Not consistent with acute trauma.'],
      ask: 'Why would the abdomen hurt in the shoulder?', cues: ['Trauma + left shoulder pain + no shoulder injury'],
      phys: 'Blood collects under the left diaphragm → irritates the phrenic nerve (C3–C5) → the brain maps the signal to the shoulder, which uses the same spinal levels → referred left shoulder pain.',
      rule: 'Kehr sign = possible splenic rupture or diaphragm irritation. Cullen = periumbilical bruising. Turner = flank bruising (retroperitoneal bleeding).' },
    { t: 'Alvimopan', q: 'Why is alvimopan given after bowel surgery?',
      o: ['It blocks opioid receptors in the gut to speed return of motility without reducing pain relief', 'It is an opioid that treats incision pain', 'It prevents nausea by acting in the brain', 'It softens stool'], a: [0],
      r: ['Correct. It is a peripherally acting mu-opioid antagonist — it works only in the gut.', 'Incorrect. It is an opioid antagonist.', 'Incorrect. It doesn’t act centrally.', 'Incorrect. Not a stool softener.'],
      ask: 'How can a drug block opioids in the gut but not in the brain?', cues: ['Postoperative ileus + opioid pain control'],
      phys: 'Opioids bind mu receptors in the gut wall → peristalsis slows (ileus) → alvimopan blocks those receptors but doesn’t cross into the brain → motility returns while analgesia continues.',
      rule: 'Alvimopan: short-term, oral, for postoperative ileus.' },
    { t: 'Best fluid measure', q: 'Which measure is most reliable for tracking fluid balance in a client with a bowel obstruction on NG suction?',
      o: ['Daily weight', 'Skin turgor', 'Thirst', 'Number of emeses'], a: [0],
      r: ['Correct. Fluid trapped in the bowel and peritoneum can’t be seen or measured; weight captures the real change.', 'Incorrect. Unreliable, especially in older adults.', 'Incorrect. Some older adults don’t feel thirst.', 'Incorrect. Much of the loss is hidden in the bowel lumen.'],
      ask: 'How do you measure fluid you can’t see?', cues: ['Third-spacing in obstruction'],
      phys: 'A blocked bowel traps fluid in its lumen and leaks plasma into the peritoneum → circulating volume falls without visible loss → body weight still changes with total water.',
      rule: 'Obstruction: daily weight is the best fluid measure; also I&O, VS, urine output, electrolytes.' },
    { t: 'Inherited colon cancer', q: 'A 19-year-old has familial adenomatous polyposis (FAP). What does the nurse expect?',
      o: ['A colectomy is usually needed by about age 20', 'Colonoscopy starting at age 45', 'Yearly FIT testing is enough', 'No increased cancer risk'], a: [0],
      r: ['Correct. FAP produces thousands of polyps with nearly 100% cancer risk, so most need colectomy (with ileostomy or ileoanal pull-through) by 20.', 'Incorrect. Age 45 is for average-risk adults.', 'Incorrect. Stool tests are for average risk.', 'Incorrect. Risk is nearly 100%.'],
      ask: 'What does an APC mutation do to the colon?', cues: ['FAP → autosomal dominant APC mutation'],
      phys: 'The APC tumor-suppressor gene is mutated → colonic cells divide unchecked → thousands of adenomatous polyps over 10–15 years → one becomes malignant.',
      rule: 'FAP: colectomy by ~20. Lynch (HNPCC): 80% lifetime risk, plus endometrial and other cancers. Teach families about genetic testing.' },
    { t: 'Perineal wound', q: 'Which comfort measure is appropriate after an abdominoperineal resection?',
      o: ['Sit on a foam pad or soft pillow, not an air ring', 'Sit on a rubber donut cushion', 'Sit upright for long periods to promote drainage', 'Avoid sitz baths until the wound is closed'], a: [0],
      r: ['Correct. Foam or a soft pillow spreads pressure; a donut stretches the perineum and reduces blood flow to the wound.', 'Incorrect. Never use an air ring or donut.', 'Incorrect. Avoid long sitting; side-lying in bed.', 'Incorrect. Sitz baths 3–4 times a day ease pain and promote healing.'],
      ask: 'What does a donut do to the wound edges?', cues: ['Perineal wound heals over months'],
      phys: 'A donut lets the perineum sag through the center → wound edges stretch apart and blood flow falls → slower healing and more pain.',
      rule: 'AP resection: sitz baths, absorbent pad, side-lying, foam cushion (never a donut), I&O with drain output, watch for infection; healing takes 6–8 months.' },
    { t: 'Stool from a colostomy', q: 'What stool consistency should the nurse expect from a descending colostomy once it is working?',
      o: ['Formed', 'Liquid', 'Pasty', 'Clear mucus only'], a: [0],
      r: ['Correct. By the descending colon most water has been absorbed.', 'Incorrect. Liquid comes from an ascending colostomy or ileostomy.', 'Incorrect. Pasty comes from a transverse colostomy.', 'Incorrect. Mucus alone comes from a distal mucous fistula.'],
      ask: 'How much water has the colon absorbed by this point?', cues: ['Descending → most water absorbed'],
      phys: 'The colon absorbs water along its length → ascending output is liquid, transverse pasty, descending formed.',
      rule: 'Colostomy output: ascending liquid, transverse pasty, descending/sigmoid formed. Starts working in 2–3 days with lots of gas.' },
    { t: 'Hydrogen breath test', q: 'Which instruction prepares a client for a hydrogen breath test?',
      o: ['Nothing to eat for at least 12 hours; water is allowed', 'Drink only clear liquids for 3 days', 'Stop all fiber for a week', 'Take a laxative the night before'], a: [0],
      r: ['Correct. After fasting, the client blows a baseline sample, drinks lactulose, then gives samples every 20 minutes for 1–2 hours.', 'Incorrect. Not the prep.', 'Incorrect. Not required.', 'Incorrect. Not part of the prep.'],
      ask: 'Why does fasting matter for a breath test?', cues: ['Breath hydrogen from gut bacteria'],
      phys: 'Bacteria fermenting carbohydrate make hydrogen → it is absorbed and exhaled → overgrowth or malabsorption raises breath hydrogen after the lactulose drink; recent food would confuse the baseline.',
      rule: 'Hydrogen breath test: NPO (water OK) 12 h → baseline → lactulose → samples every 20 min for 1–2 h.' },
    { t: 'IBS fiber', q: 'A client with IBS asks why fiber is recommended for both diarrhea and constipation. Which response is accurate?',
      o: ['Soluble fiber holds water — it softens hard stool and firms loose stool', 'Fiber speeds the bowel in everyone', 'Fiber only helps constipation; it was recommended by mistake', 'Fiber kills the bacteria that cause IBS'], a: [0],
      r: ['Correct. Psyllium absorbs water into a gel, pulling stool toward a soft, bulky middle.', 'Incorrect. It normalizes rather than speeds.', 'Incorrect. It helps both types.', 'Incorrect. Fiber isn’t antibacterial.'],
      ask: 'How can one product help opposite problems?', cues: ['IBS-C and IBS-D both get fiber'],
      phys: 'Soluble fiber forms a gel that holds water → in constipation it adds water and bulk → in diarrhea it binds excess water → stool moves toward normal form.',
      rule: 'IBS: 30–40 g fiber, 8–10 glasses of water, regular meals, exercise, stress care; drugs by type.' },
    { t: 'Holding pain medicine', q: 'Why might the provider hold opioids briefly while a suspected bowel obstruction is being worked up?',
      o: ['A change in the pain pattern can show strangulation or perforation', 'Opioids cause the obstruction', 'The client is not really in pain', 'Opioids interfere with CT scans'], a: [0],
      r: ['Correct. Colicky pain turning constant — or stopping and becoming tenderness — is the diagnosis; opioids can mask it (and morphine slows motility).', 'Incorrect. They slow motility but don’t cause mechanical obstruction.', 'Incorrect. The pain is real; explain why and use non-drug comfort.', 'Incorrect. Not a CT issue.'],
      ask: 'What is the best real-time monitor in this chapter?', cues: ['Pain pattern = diagnosis'],
      phys: 'Colic = the bowel fighting a block → constant or localized pain = the wall losing blood supply → sudden relief with tenderness = perforation → masking these hides the moment surgery is needed.',
      rule: 'Report pain that becomes constant or localized, or stops suddenly; explain why analgesia may be limited; comfort with positioning (semi-Fowler).' },
    { t: 'Odor from the pouch', q: 'A client with a colostomy reports a strong odor all day. What should the nurse check first?',
      o: ['Whether the pouch is leaking or poorly closed', 'Whether the client is eating enough fiber', 'Whether the stoma is infected', 'Whether the client needs a larger pouch'], a: [0],
      r: ['Correct. Odor usually means a leak or a poorly closed pouch.', 'Incorrect. Diet affects gas, but constant odor points to a leak.', 'Incorrect. Not the first thought.', 'Incorrect. Fit matters, but check for a leak first.'],
      ask: 'What does a sealed pouch do to odor?', cues: ['Odor-proof pouches → odor means a leak'],
      phys: 'Modern pouches are odor-proof when sealed → odor escapes only through a broken seal or open end → a leak also exposes skin to stool.',
      rule: 'Odor: check the seal and closure first; filters and deodorizers; avoid gas-producing foods; never aspirin in the pouch.' },
    { t: 'Colorectal cancer signs', q: 'Which finding should the nurse report as a possible sign of colorectal cancer?',
      o: ['A change in stool shape with blood in the stool', 'One hard stool after a long trip', 'Mild gas after eating beans', 'Stool that floats occasionally'], a: [0],
      r: ['Correct. Rectal bleeding, anemia and a change in stool consistency or shape are the most common signs.', 'Incorrect. A one-time change with a clear cause isn’t concerning.', 'Incorrect. Expected.', 'Incorrect. Not a cancer sign on its own.'],
      ask: 'Which changes persist and point to the colon?', cues: ['Blood + change in shape'],
      phys: 'A tumor bleeds from its fragile surface and narrows the lumen → blood in stool, narrow or changed stool, and over time anemia, fatigue and weight loss.',
      rule: 'CRC signs: rectal bleeding, anemia, change in bowel habits or stool shape; fatigue, fullness and weight loss suggest advanced disease.' },
    { t: 'Linaclotide teaching', q: 'A 29-year-old woman with constipation-predominant irritable bowel syndrome (IBS-C) is starting linaclotide. Which instruction should the nurse give?',
      o: ['Take it once a day about 30 minutes before breakfast', 'Take it with your largest meal to prevent nausea', 'Take it only on days you have not had a bowel movement', 'Take it at bedtime with an antihistamine to help you sleep'], a: [0],
      r: ['Correct. Linaclotide is taken once daily about 30 minutes before breakfast. It draws fluid into the intestine, speeds transit and eases pain and cramping.', 'Incorrect. Taking the drug with food and water is the teaching for lubiprostone, another IBS-C drug — not linaclotide.', 'Incorrect. It is a scheduled daily drug, not a rescue laxative.', 'Incorrect. There is no reason to pair it with an antihistamine; the warning about antihistamines and psychoactive drugs belongs to alosetron.'],
      ask: 'Which IBS-C drug has the before-breakfast timing?', cues: ['IBS-C', 'Linaclotide → once daily, 30 min before breakfast'],
      phys: 'Linaclotide stimulates guanylate cyclase receptors on the intestinal lining → the cells secrete more fluid into the lumen → stool softens and moves faster → pain and cramping ease.',
      rule: 'IBS-C: linaclotide once daily 30 min before breakfast; lubiprostone (women) with food and water; psyllium at meals with a full glass of water.' },
    { t: 'Watching a liver injury', q: 'A client with a liver laceration from blunt abdominal trauma is being managed without surgery in the ICU. Which finding should the nurse report to the surgeon immediately?',
      o: ['Hemoglobin 13.2 → 10.1 g/dL over 4 hours, with heart rate 88 → 118', 'Abdominal pain steady at 4/10 since admission', 'Hypoactive bowel sounds', 'Urine output 50 mL/hr'], a: [0],
      r: ['Correct. A falling hemoglobin with a rising heart rate means continued bleeding — deterioration under observation can mean the client needs a laparotomy.', 'Incorrect. Pain that holds steady is reassuring; worsening pain is what signals bleeding, perforation or abdominal compartment syndrome.', 'Incorrect. Bowel sounds are often decreased after abdominal trauma (bleeding, organ injury, ileus); on its own this isn’t the urgent finding.', 'Incorrect. Adequate output — above 30 mL/hr.'],
      ask: 'Which trend shows the bleeding hasn’t stopped?', cues: ['Hgb falling + HR rising', 'Nonsurgical observation → watch for deterioration'],
      phys: 'A torn liver keeps bleeding into the abdomen → red cell mass falls (Hgb, Hct) → the heart speeds up to hold cardiac output → without control, hypovolemic shock follows → surgery stops the bleeding.',
      rule: 'Abdominal trauma under ICU observation: frequent VS, pain and Hgb/Hct; transfuse for active bleeding; a falling Hgb, rising pulse or worsening pain → report → possible laparotomy. Stable for 24–48 h → transfer.' },
    { t: 'After an abdominoperineal resection', q: 'Three days after an abdominoperineal (AP) resection, a client has a closed perineal wound with two Jackson-Pratt drains. Which finding should the nurse report first?',
      o: ['Temperature 101.6°F with cloudy, foul-smelling drainage from the perineal wound', 'Serosanguineous drainage in the drains', 'A feeling of needing to pass stool through the rectum', 'Perineal pain that increases with sitting'], a: [0],
      r: ['Correct. The perineal wound is at high risk for infection and abscess — fever with cloudy, foul drainage is the priority to report.', 'Incorrect. Serosanguineous drainage is expected and may continue for 1–2 months.', 'Incorrect. Phantom rectal sensations are common because the sympathetic nerves for rectal control were not cut.', 'Incorrect. Expected — the perineal wound often hurts more than the abdominal incision; side-lying, a foam cushion and sitz baths help.'],
      ask: 'Which finding is expected after an AP resection, and which means a complication?', cues: ['Perineal wound + drains → infection and abscess risk', 'Fever + cloudy, foul drainage'],
      phys: 'Removing the rectum and anus leaves a perineal wound and cavity near a heavily colonized area → drainage that collects lets bacteria multiply → infection or abscess → fever and cloudy, foul drainage.',
      rule: 'After AP resection the priority problem for the perineal wound is infection. Expected: serosanguineous drainage for 1–2 months, phantom rectal sensations, more pain than the abdominal incision. Report fever, foul or purulent drainage, redness, swelling or constant pain.' },
    { t: 'Ascending colostomy teaching', q: 'A client with a right-sided colon tumor now has an ascending colostomy. Which statement shows that the client understands the teaching?',
      o: ['“My stool will stay liquid, so I’ll keep my pouch on all the time.”', '“I’ll irrigate my colostomy each morning so I can go without a pouch.”', '“I’ll wait until the pouch is completely full before I empty it.”', '“My stoma will get bigger over the next 6 weeks, so I’ll cut the opening larger.”'], a: [0],
      r: ['Correct. Stool from the ascending colon stays liquid and drains often, so the pouch is worn at all times.', 'Incorrect. Irrigation can regulate a sigmoid colostomy, which passes formed stool — not an ascending one.', 'Incorrect. Empty it at one-third to one-half full; a heavy pouch pulls on the seal and leaks.', 'Incorrect. The stoma shrinks over 6–8 weeks; measure it weekly and cut the opening ⅛–1/16 inch larger than the stoma.'],
      ask: 'What does the stoma’s location tell you about its output?', cues: ['Right-sided tumor → ascending colostomy', 'Ascending → liquid stool'],
      phys: 'The colon absorbs water along its length → an ascending stoma diverts stool before most water is absorbed → output is liquid and frequent → a pouch must always be on; a sigmoid stoma passes formed stool that irrigation can regulate.',
      rule: 'Colostomy site follows the tumor (Fig. 48.4): ascending (right), descending (left), sigmoid (rectal), transverse double-barrel in emergencies. Ascending = liquid, pouch always on; empty at ⅓–½ full; stoma shrinks 6–8 weeks; alcohol-free sealant before the wafer.' },
    { t: 'Large-bowel obstruction in an older adult', q: 'An 84-year-old resident of a long-term care facility who takes an opioid for arthritis has had no bowel movement for 6 days. The lower abdomen is distended, cramping comes and goes, and there has been little vomiting. Which cause of this large-bowel obstruction should the nurse suspect first?',
      o: ['Fecal impaction', 'Volvulus', 'Adhesions from surgery', 'Intussusception'], a: [0],
      r: ['Correct. Older adults are the group most likely to have a bowel obstruction, usually from fecal impaction or a tumor; slower peristalsis, opioids and constipation set it up. A low impaction usually resolves with disimpaction and enemas.', 'Incorrect. Twisting of the bowel is a possible mechanical cause but much less likely than impaction in this client.', 'Incorrect. Adhesions follow abdominal surgery, and none is described.', 'Incorrect. Telescoping of the bowel has nothing in this history to suggest it.'],
      ask: 'Which cause fits an older adult with constipation and opioid use?', cues: ['Older adult + opioid + no BM for 6 days', 'Lower distention, little vomiting → large bowel'],
      phys: 'Aging slows peristalsis → opioids slow it further → stool stays in the colon and dries → a hard mass forms (impaction) → stool and gas back up behind it → lower distention and cramping.',
      rule: 'Older adults: obstruction is most often fecal impaction or cancer. Prevent impaction with fiber, water, daily walks, warm drinks or prune juice, bulk formers and softeners — not routine laxatives (atonic colon).' },
    { t: 'Going home after hernia repair', q: 'Four hours after a minimally invasive inguinal hernia repair, the nurse reviews discharge teaching. Which statement by the client needs follow-up?',
      o: ['“I’ll drive myself to work tomorrow while I’m taking the oxycodone.”', '“Some soreness is normal, but I’ll call if the pain gets much worse.”', '“I’ll take the stool softener so I don’t strain.”', '“I won’t lift anything heavier than 10 pounds until the surgeon says it’s OK.”'], a: [0],
      r: ['Correct — needs follow-up. Clients taking oral opioids must not drive or operate heavy machinery, and return to work is usually in 1–2 weeks, when the surgeon allows.', 'Incorrect. Accurate: soreness and discomfort are expected; severe or increasing pain is reported.', 'Incorrect. Accurate: a stool softener prevents constipation and straining on the repair.', 'Incorrect. Accurate: no lifting over 10 lb (4.5 kg) until cleared.'],
      ask: 'Which plan is unsafe after same-day hernia repair?', cues: ['Opioid + driving', '“Needs follow-up” → find the wrong statement'],
      phys: 'Opioids depress the central nervous system → drowsiness and slower reactions → driving or using machinery is unsafe; straining and lifting raise intraabdominal pressure on the fresh repair.',
      rule: 'After MIIHR: home in 3–5 h with an adult; no driving on opioids; soreness expected, severe pain reported; stool softener; ≤ 10 lb lifting; deep breathe, don’t cough; report fever, redness or drainage; follow-up call the next day.' }
  ],
  rq: [
    ['Fill in the chain', 1, 'Bowel blocked → ___ → bowel wall ___ → ___ → strangulation → ___.',
      'Contents and gas pile up above the block, peristalsis and secretions increase → the wall swells and leaks plasma → hypovolemia and electrolyte loss → ischemia → peritonitis and sepsis.',
      'Fluid is trapped in the lumen and peritoneum, not lost visibly.',
      'NPO, NG to low continuous suction, IV isotonic fluid with K⁺, daily weight.',
      'A rising pulse and fever over 100°F mean strangulation, not routine obstruction.'],
    ['Compare and contrast', 1, 'Compare small- and large-bowel obstruction.',
      'Small: upper/epigastric distention, early profuse vomiting (may be feculent), severe fluid and electrolyte loss, possible metabolic alkalosis. Large: lower distention, intermittent lower cramping, little or no vomiting, ribbon-like stools or obstipation, possible metabolic acidosis.',
      'The height of the block decides what is lost and how fast.',
      'CT or MRI as soon as obstruction is suspected.',
      'The ileum, the narrowest part, is the most common site.'],
    ['Direct recall', 1, 'Describe a healthy stoma and what to report.',
      'Healthy: reddish pink to dark red-pink, moist, protruding 1–3 cm; slight edema and a little bleeding early are common. Report: dark red, purple or black, or dry (ischemia, necrosis); continuous heavy bleeding; mucocutaneous separation.',
      'Color is the only window into the stoma’s blood supply.',
      'Use a clear pouch early so the stoma can be seen.',
      'The stoma has no pain nerves, so the client won’t feel it being cut.'],
    ['Which finding changes the priority?', 1, 'In a client with a bowel obstruction, which findings mean strangulation or perforation?',
      'Temperature above 100°F with a sustained rise in pulse; pain that changes from colicky to constant or localized, or stops and becomes tenderness; guarding, rigidity; hypotension; a color change of the abdominal skin.',
      'Ischemic bowel stops contracting and leaks bacteria and endotoxin.',
      'Report at once and prepare for surgery.',
      'Opioids can mask the change in pain.'],
    ['Direct recall', 1, 'Teach the care after a hernia repair.',
      'Deep breathing and incentive spirometry but no coughing; walk within hours; ice; scrotal support and elevation after indirect inguinal repair; stand to void, report UO < 30 mL/hr; 1500–2500 mL fluid a day; lift ≤ 10 lb; fiber and fluids, no straining; report fever.',
      'Every rule avoids pressure on the fresh repair or catches urinary retention.',
      'Follow-up call the next day.',
      'Never force a hernia back before surgery.'],
    ['Compare and contrast', 0, 'Compare right-sided and left-sided colorectal cancer.',
      'Right (ascending): liquid stool, so bowel habits don’t change; intermittent mahogany blood, anemia, RLQ mass. Left/rectosigmoid: obstruction, “gas pains”, narrow stools, straining, bright red blood.',
      'Stool is liquid on the right and formed on the left.',
      'Colonoscopy is definitive; CEA monitors.',
      'Unexplained anemia in an older adult can be right-sided colon cancer.'],
    ['Medication-focused', 0, 'Name the IBS drugs by type and one key teaching point each.',
      'IBS-C: psyllium (with water), lubiprostone (women, with food and water), linaclotide (30 min before breakfast). IBS-D: loperamide, psyllium, alosetron (women, last resort — report constipation or bloody diarrhea: ischemic colitis), rifaximin (bloating). Pain: tricyclics like amitriptyline.',
      'Each drug adds fluid, slows transit or reduces sensitivity.',
      'Take a full drug history before alosetron.',
      'IBS labs are normal — weight loss or bleeding point elsewhere.'],
    ['Direct recall', 1, 'What preparation does a stool test for occult blood (FOBT or FIT) need?',
      'It depends on the type of test. Some call for no aspirin, vitamin C, iron or red meat for the 48 hours before and stop antiinflammatory drugs (ibuprofen, corticosteroids, salicylates) for a set period; FOBT uses 2–3 samples on 3 consecutive days. Ch 45’s guaiac schedule: no NSAIDs for 7 days, no red meat or vitamin C over 250 mg for 3 days; FIT needs no preparation.',
      'Some foods, vitamins and drugs throw off the result, and aspirin and other antiinflammatory drugs can make the GI tract bleed on their own.',
      'Check which test is ordered, teach that test’s preparation, and review the drug list.',
      'A negative result does not rule out colorectal cancer.']
  ],
  mc: [
    ['Listen for bowel sounds with the NG suction running.', 'Turn the suction off before listening for bowel sounds.', 'Peristalsis is “heard” when it isn’t there.', 'The suction itself gurgles.'],
    ['A donut cushion eases sitting after an AP resection.', 'Use a foam pad or soft pillow — never an air ring or donut.', 'The wound edges stretch and heal more slowly.', 'A donut lets the perineum sag and reduces blood flow to the wound.'],
    ['An incarcerated hernia should be pushed back in.', 'Never force a hernia back; an irreducible hernia needs immediate surgical evaluation.', 'Strangulated bowel could rupture.', 'The trapped loop may already be ischemic.'],
    ['An aspirin in the pouch controls colostomy odor.', 'Never put aspirin in the pouch; odor usually means a leak.', 'Aspirin can ulcerate the stoma.', 'Aspirin is irritating to exposed mucosa.'],
    ['A negative stool blood test rules out colon cancer.', 'A negative FOBT or FIT does not rule out colorectal cancer.', 'Symptoms get dismissed and diagnosis is delayed.', 'Tumors bleed intermittently, so a sample can miss it.'],
    ['Fiber makes IBS diarrhea worse.', 'Soluble fiber such as psyllium helps both IBS-C and IBS-D.', 'Clients skip a treatment that works.', 'It holds water and normalizes stool form in both directions.'],
    ['Cut the wafer opening exactly the size of the stoma.', 'Measure weekly and cut the opening ⅛–1/16 inch larger than the stoma.', 'The wafer edge cuts a stoma that can’t feel pain.', 'The stoma shrinks for 6–8 weeks after surgery.'],
    ['A laxative every night keeps an older adult regular and prevents impaction.', 'Avoid routine laxatives; prevent constipation with fiber, plenty of water (8–10 glasses a day unless fluids are restricted), daily walks, warm drinks or prune juice, and bulk formers or softeners if needed.', 'Overuse weakens abdominal muscle tone and leads to an atonic colon — the setup for the impaction it was meant to prevent.', 'Stimulant laxatives replace the bowel’s own reflex instead of training it, so the reflex fades and the colon stretches and slows.']
  ]
};
